import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './index.css'; // We'll update CSS below too

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);

  // Form
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});

  // Courses & Enrollment
  const [courses, setCourses] = useState([]);
  const [enrolledCourseIds, setEnrolledCourseIds] = useState([]);

  // Submission (text)
  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [submissionText, setSubmissionText] = useState('');

  // View submission
  const [showFileModal, setShowFileModal] = useState(false);
  const [currentSubmissionText, setCurrentSubmissionText] = useState('');
  const [currentSubmissionId, setCurrentSubmissionId] = useState(null);

  // Grade (instructor)
  const [showGradeModal, setShowGradeModal] = useState(false);
  const [submissionToGrade, setSubmissionToGrade] = useState(null);
  const [gradeValue, setGradeValue] = useState('');
  const [feedbackText, setFeedbackText] = useState('');

  // Delete
  const [showConfirmDelete, setShowConfirmDelete] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);
  const [deleteBase, setDeleteBase] = useState('');

  const API = 'http://localhost:5000/api';

  // ... (all your existing functions: getEndpoint, getEmptyForm, login, logout, load, goTo, useEffect, enroll, drop, submitAssignment, viewSubmission, requestDeleteSubmission, gradeSubmission, saveGrade, confirmDelete, startAdd, startEdit, saveItem, etc. remain the same)

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Login Page */}
      {page === 'login' && !user && (
        <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 to-indigo-700">
          <div className="bg-white p-10 rounded-2xl shadow-2xl w-full max-w-md">
            <h1 className="text-3xl font-bold text-center text-gray-800 mb-8">NM Student Portal</h1>
            <form onSubmit={login} className="space-y-6">
              <input
                type="email"
                placeholder="Enter your email"
                value={emailInput}
                onChange={(e) => setEmailInput(e.target.value)}
                required
                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
              <button type="submit" className="w-full bg-blue-600 text-white py-3 rounded-lg font-semibold hover:bg-blue-700 transition">
                Login
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Main App */}
      {user && (
        <div className="flex h-screen bg-gray-100">
          {/* Sidebar */}
          <aside className="w-64 bg-white shadow-lg">
            <div className="p-6 border-b">
              <h2 className="text-2xl font-bold text-blue-600">NM Portal</h2>
              <p className="text-sm text-gray-600 mt-1">Welcome, {user.name}</p>
            </div>
            <nav className="mt-6">
              <button onClick={() => goTo('courses')} className={`w-full text-left px-6 py-3 hover:bg-blue-50 ${page === 'courses' ? 'bg-blue-100 border-l-4 border-blue-600' : ''}`}>
                📚 Courses
              </button>
              {user.role === 'student' && (
                <>
                  <button onClick={() => goTo('assignments')} className={`w-full text-left px-6 py-3 hover:bg-blue-50 ${page === 'assignments' ? 'bg-blue-100 border-l-4 border-blue-600' : ''}`}>
                    📝 Assignments
                  </button>
                  <button onClick={() => goTo('announcements')} className={`w-full text-left px-6 py-3 hover:bg-blue-50 ${page === 'announcements' ? 'bg-blue-100 border-l-4 border-blue-600' : ''}`}>
                    📢 Announcements
                  </button>
                  <button onClick={() => goTo('submissions')} className={`w-full text-left px-6 py-3 hover:bg-blue-50 ${page === 'submissions' ? 'bg-blue-100 border-l-4 border-blue-600' : ''}`}>
                    📤 My Submissions
                  </button>
                </>
              )}
              {user.role === 'instructor' && (
                <>
                  <button onClick={() => goTo('assignments')} className={`w-full text-left px-6 py-3 hover:bg-blue-50 ${page === 'assignments' ? 'bg-blue-100 border-l-4 border-blue-600' : ''}`}>
                    📝 Assignments
                  </button>
                  <button onClick={() => goTo('announcements')} className={`w-full text-left px-6 py-3 hover:bg-blue-50 ${page === 'announcements' ? 'bg-blue-100 border-l-4 border-blue-600' : ''}`}>
                    📢 Announcements
                  </button>
                  <button onClick={() => goTo('submissions')} className={`w-full text-left px-6 py-3 hover:bg-blue-50 ${page === 'submissions' ? 'bg-blue-100 border-l-4 border-blue-600' : ''}`}>
                    ✅ Grade Submissions
                  </button>
                  <button onClick={() => goTo('students')} className={`w-full text-left px-6 py-3 hover:bg-blue-50 ${page === 'students' ? 'bg-blue-100 border-l-4 border-blue-600' : ''}`}>
                    👥 Students
                  </button>
                </>
              )}
              <button onClick={logout} className="w-full text-left px-6 py-3 mt-8 text-red-600 hover:bg-red-50">
                🚪 Logout
              </button>
            </nav>
          </aside>

          {/* Main Content */}
          <main className="flex-1 overflow-y-auto">
            <header className="bg-white shadow-sm px-8 py-6">
              <h1 className="text-3xl font-bold text-gray-800">{page.charAt(0).toUpperCase() + page.slice(1)}</h1>
              {user.role === 'instructor' && ['courses', 'assignments', 'announcements', 'students'].includes(page) && (
                <button onClick={startAdd} className="mt-4 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition">
                  + Add New {page.slice(0, -1)}
                </button>
              )}
            </header>

            <div className="p-8">
              {loading && <p className="text-center text-gray-600">Loading...</p>}

              {!loading && data.length === 0 && <p className="text-center text-gray-600">No {page} available.</p>}

              {data.length > 0 && (
                <div className="grid gap-6 md:grid-cols-1 lg:grid-cols-1">
                  {data.map(item => (
                    <div key={item.id} className="bg-white rounded-xl shadow-md p-6 hover:shadow-lg transition">
                      {/* Your existing table rows converted to cards for better look */}
                      <div className="flex justify-between items-start">
                        <div>
                          <h3 className="text-xl font-semibold text-gray-800">{item.title || `Item ${item.id}`}</h3>
                          <p className="text-gray-600 mt-2">{item.description || item.message || '—'}</p>
                          {item.duedate && <p className="text-sm text-gray-500 mt-1">Due: {item.duedate}</p>}
                          {item.courseid && <p className="text-sm text-gray-500">Course ID: {item.courseid}</p>}
                        </div>
                        <div className="flex gap-3">
                          {/* Actions based on page/role */}
                          {/* (Keep all your existing buttons here, just styled better) */}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </main>
        </div>
      )}

      {/* All your modals remain the same but with updated styling classes */}
      {/* ... (keep your existing modals with className updates for bg-white, rounded-xl, etc.) */}

      <footer className="bg-gray-800 text-white text-center py-6 mt-auto">
        <h3 className="text-xl font-bold">NM Student Portal © 2025</h3>
        <p className="mt-2">Full Role-Based System • Professional Learning Platform</p>
      </footer>
    </div>
  );
}

export default App;
